/**
 * The contract `file-picker.tsx` (native) and `file-picker.web.tsx` implement.
 *
 * Its own module for the usual reason — Metro resolves `./file-picker` to the
 * `.web.tsx` file on web, so that file cannot import the shared pieces from
 * `./file-picker` without importing itself.
 */

export type FilePickerProps = {
  /**
   * Handed the picked file's decoded text, never the `File` object itself.
   * `File` is DOM-only, so a contract carrying one could not be implemented on
   * native — and the calling screen only ever wants the text anyway.
   */
  onPick: (text: string, fileName: string) => void;
  /** e.g. `"application/json,.json"`. Web only — advisory on the dialog. */
  accept?: string | undefined;
  label: string;
  hint?: string | undefined;
};

/**
 * The native file picker — a placeholder, not an implementation.
 *
 * **This half does not pick a file.** Reading one off web needs
 * `expo-document-picker` and a file-system read for the URI it returns, both of
 * which are app-level choices with their own permission flow — so rather than
 * ship a drop zone that silently opens nothing, this says so on screen and
 * `onPick` is never called. Replace this file in your app once those are wired
 * up; `file-picker-base.ts` is the contract to implement, and
 * `file-picker.web.tsx` is a working reference for the shape.
 */
import { Text, View } from "react-native";
import type { FilePickerProps } from "@/components/ui/file-picker-base";
import { Upload } from "@/components/ui/icons";

export function FilePicker({ label }: FilePickerProps) {
  return (
    <View className="w-full flex-col items-center gap-2 rounded-xl border-2 border-dashed border-muted-foreground/25 px-6 py-12">
      <Upload className="h-8 w-8 text-muted-foreground" />
      <Text className="text-center text-sm font-medium text-foreground">{label}</Text>
      <Text className="text-center text-xs text-muted-foreground">
        Picking a file is only available on the web app.
      </Text>
    </View>
  );
}

/**
 * The web file picker: a drop zone over a hidden `<input type="file">`.
 *
 * Both are DOM-only, which is why this is a `.web.tsx`. The caller never sees a
 * `File` — it gets the decoded text — so the calling screen stays shared.
 */
import { useRef, useState } from "react";
import { Text } from "react-native";
import type { FilePickerProps } from "@/components/ui/file-picker-base";
import { Upload } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

export function FilePicker({ onPick, accept, label, hint }: FilePickerProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false);

  async function read(file: File) {
    onPick(await file.text(), file.name);
  }

  return (
    <>
      <button
        type="button"
        onClick={() => inputRef.current?.click()}
        onDragOver={(e) => {
          e.preventDefault();
          setDragging(true);
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(e) => {
          e.preventDefault();
          setDragging(false);
          const file = e.dataTransfer.files?.[0];
          if (file) void read(file);
        }}
        className={cn(
          "w-full flex-col items-center gap-2 rounded-xl border-2 border-dashed px-6 py-12 text-center transition-colors",
          dragging
            ? "border-primary bg-primary/5"
            : "border-muted-foreground/25 hover:border-muted-foreground/50",
        )}
      >
        <Upload className="h-8 w-8 text-muted-foreground" />
        <Text className="font-medium text-sm">{label}</Text>
        {hint ? <Text className="text-xs text-muted-foreground">{hint}</Text> : null}
      </button>
      <input
        ref={inputRef}
        type="file"
        {...(accept ? { accept } : {})}
        className="hidden"
        onChange={(e) => {
          const file = e.target.files?.[0];
          if (file) void read(file);
          // Allow re-selecting the same file after a reset.
          e.target.value = "";
        }}
      />
    </>
  );
}
